    ('Volkswagen', 'Taigo', 'Taigo I', 2021, NULL::int, NULL::text, 'https://en.wikipedia.org/wiki/Volkswagen_Taigo'::text),
    ('Volkswagen', 'Touareg', 'Touareg I (7L)', 2002, 2009::int, NULL::text, 'https://en.wikipedia.org/wiki/Volkswagen_Touareg'::text),
    ('Volkswagen', 'Touareg', 'Touareg II (7P)', 2010, 2017::int, NULL::text, 'https://en.wikipedia.org/wiki/Volkswagen_Touareg'::text),
    ('Volkswagen', 'Touareg', 'Touareg III (CR)', 2018, 2026::int, NULL::text, 'https://en.wikipedia.org/wiki/Volkswagen_Touareg'::text),
    ('Volvo', 'C30', 'C30', 2006, 2013::int, NULL::text, 'https://en.wikipedia.org/wiki/Volvo_C30'::text),
    ('Volvo', 'C40', 'C40 Recharge', 2021, 2023::int, NULL::text, 'https://en.wikipedia.org/wiki/Volvo_EC40'::text),
    ('Volvo', 'C40', 'EC40', 2024, NULL::int, NULL::text, 'https://en.wikipedia.org/wiki/Volvo_EC40'::text),
    ('Volvo', 'EX90', 'EX90 I', 2024, NULL::int, NULL::text, 'https://en.wikipedia.org/wiki/Volvo_EX90'::text),
    ('Volvo', 'V50', 'V50 (P1)', 2004, 2012::int, NULL::text, 'https://en.wikipedia.org/wiki/Volvo_S40'::text)
) AS v(brand, model, name, year_start, year_end, fuel_type, source_url)
JOIN brands b ON b.name = v.brand
JOIN vehicle_models vm ON vm.brand_id = b.id AND vm.name = v.model
WHERE NOT EXISTS (SELECT 1 FROM generations g WHERE g.model_id = vm.id AND g.name = v.name);

INSERT INTO driving_character
    (model_id, comfort_score, driving_fun_score, city_score, highway_score, family_score, noise_level, description)
SELECT vm.id, v.comfort, v.fun, v.city, v.highway, v.family, v.noise, v.description
FROM (VALUES
    ('Abarth', '124 Spider', 5, 9, 6, 5, 1, 'alto', 'Roadster de dois lugares e tração traseira com base Mazda MX-5 e motor 1.4 turbo de 170 cv. Leve e muito divertido; bagageira pequena e habitáculo apertado.'),
    ('Abarth', '500e', 5, 7, 9, 4, 2, 'baixo', 'Citadino elétrico de 155 cv, ágil e rápido a baixa velocidade, com gerador de som opcional a imitar o motor a gasolina. Autonomia real curta e lugares traseiros simbólicos.'),
    ('Abarth', '500e Cabrio', 5, 7, 9, 4, 2, 'baixo', 'Abarth 500e com capota de lona deslizante. Mesma mecânica de 155 cv e a mesma autonomia curta; a capota aberta reduz a visibilidade traseira.'),
    ('Abarth', '595', 4, 8, 8, 4, 2, 'alto', 'Fiat 500 com motor 1.4 turbo de 135 a 180 cv. Divertido, ruidoso e fácil de estacionar; suspensão dura, posição de condução alta e pouco espaço atrás.'),
    ('Abarth', '595C', 4, 8, 8, 4, 2, 'alto', 'Versão de capota de lona deslizante do Abarth 595: os pilares e as portas mantêm-se, só o tejadilho abre. Mesmo carácter ruidoso e firme, com bagageira de acesso mais estreito.'),
    ('Abarth', '600e', 5, 8, 7, 6, 5, 'medio', 'Crossover elétrico de 240 ou 280 cv com diferencial autoblocante. Rápido e eficaz em curva, mas com suspensão firme e autonomia curta para viagens.'),
    ('Alfa Romeo', 'Giulietta', 6, 7, 6, 7, 5, 'medio', 'Compacto de cinco portas com bom comportamento e direção rápida. Habitabilidade traseira e ergonomia fracas; fiabilidade elétrica irregular.'),
    ('Alfa Romeo', 'Junior', 7, 6, 8, 6, 4, 'baixo', 'SUV urbano em híbrido ligeiro ou elétrico. Ágil para a classe; lugares traseiros apertados.'),
    ('Alfa Romeo', 'MiTo', 5, 6, 8, 5, 3, 'medio', 'Utilitário de três portas com estilo e motores vivos. Suspensão seca e pouco espaço atrás.'),
    ('Alfa Romeo', 'Tonale', 7, 7, 6, 8, 6, 'baixo', 'SUV compacto com direção rápida e comportamento acima da média. Híbridos ligeiros pouco refinados em arranque; mala reduzida no plug-in.'),
    ('Audi', 'A7 Sportback', 8, 6, 4, 9, 6, 'baixo', 'Berlina de cinco portas com linha de coupé, baseada no A6. Estradista confortável e com bagageira prática; grande em cidade e cara de manter.'),
    ('Audi', 'A8', 10, 6, 3, 10, 7, 'baixo', 'Berlina de luxo com tração integral e carroçaria em alumínio. Muito confortável e silenciosa; suspensão pneumática e eletrónica complexa encarecem a manutenção.'),
    ('Audi', 'Q4 e-tron', 8, 5, 7, 8, 7, 'baixo', 'SUV elétrico compacto sobre a plataforma MEB. Espaçoso, confortável e fácil de conduzir; pouco entusiasmante e com carregamento apenas mediano nas primeiras versões.'),
    ('Audi', 'Q6 e-tron', 9, 6, 5, 9, 7, 'baixo', 'SUV elétrico médio sobre a plataforma PPE de 800 V. Carregamento rápido, boa autonomia e interior tecnológico; preço elevado.'),
    ('Audi', 'R8', 5, 10, 3, 8, 1, 'alto', 'Superdesportivo de motor central V8 ou V10 atmosférico. Utilizável no dia a dia para a categoria; consumos e custos de manutenção muito elevados.'),
    ('Audi', 'RS3', 6, 9, 6, 8, 5, 'alto', 'Compacto desportivo de cinco cilindros turbo e tração integral. Aceleração e som muito fortes; suspensão firme, consumos altos e seguro caro.'),
    ('Audi', 'RS5', 7, 9, 4, 9, 4, 'medio', 'Desportivo de tração integral da gama A5: V8 atmosférico na primeira geração, V6 biturbo na segunda e híbrido plug-in na terceira. Rápido e seguro, mais eficaz do que emotivo.'),
    ('Audi', 'RS6 Avant', 8, 9, 3, 10, 8, 'medio', 'Carrinha familiar com motor V8 biturbo e tração integral. Junta prestações de superdesportivo a espaço de carrinha; consumos, pneus e travões muito caros.'),
    ('Audi', 'e-tron', 9, 6, 4, 9, 7, 'baixo', 'Primeiro SUV elétrico da Audi. Muito silencioso, confortável e bem construído; pesado, com consumo elevado e autonomia real limitada nas versões 50.'),
    ('Audi', 'e-tron GT', 8, 9, 3, 9, 4, 'baixo', 'Berlina desportiva elétrica com a base técnica do Porsche Taycan. Muito rápida e estável, com carregamento de 800 V; espaço traseiro e bagageira reduzidos.'),
    ('BMW', 'M2', 5, 10, 5, 7, 2, 'alto', 'Coupé desportivo de seis cilindros e tração traseira. Muito rápido e envolvente; suspensão dura, consumos e manutenção elevados.'),
    ('BMW', 'Série 2 Coupé', 6, 8, 6, 7, 3, 'baixo', 'Coupé compacto de tração traseira. Divertido e bem construído; dois lugares traseiros de recurso.'),
    ('BMW', 'Série 6', 8, 7, 4, 9, 4, 'baixo', 'Grande coupé de viagem, também em cabrio e Gran Coupé de quatro portas. Rápido e confortável em autoestrada; pesado, e a manutenção é cara.'),
    ('BMW', 'Série 6 Gran Turismo', 9, 5, 4, 10, 8, 'baixo', 'Cinco portas grande, sucessor do Série 5 GT. Muito espaço atrás e mala enorme, suspensão confortável; pouco ágil e de desenho pouco consensual.'),
    ('BMW', 'Série 7', 10, 6, 3, 10, 8, 'baixo', 'Berlina de topo da BMW. Conforto e silêncio de referência em viagem; grande para cidade, e a eletrónica e a suspensão pneumática são caras de reparar com a idade.'),
    ('BMW', 'Série 8', 8, 8, 3, 10, 3, 'baixo', 'Grande coupé de luxo, também em cabrio e Gran Coupé. Muito rápido e estável em autoestrada; lugares traseiros simbólicos no coupé e custos elevados.'),
    ('BMW', 'X2', 7, 7, 7, 8, 5, 'baixo', 'Versão mais baixa e desportiva do X1. Conduz-se bem, mas tem menos espaço atrás e na mala e a suspensão é firme.'),
    ('BMW', 'X4', 8, 7, 5, 9, 6, 'baixo', 'X3 com tejadilho de coupé. Mesma mecânica e comportamento, menos mala e menos altura atrás, preço superior.'),
    ('BMW', 'X7', 10, 5, 2, 10, 10, 'baixo', 'O maior SUV da BMW, com sete lugares de adulto. Conforto de topo em viagem; enorme para as ruas e os estacionamentos portugueses.'),
    ('BMW', 'XM', 7, 7, 2, 9, 6, 'medio', 'SUV híbrido plug-in da divisão M, com motor V8. Muito potente e muito pesado; suspensão firme e preço de supercarro.'),
    ('BMW', 'i3', 6, 7, 9, 5, 4, 'baixo', 'Citadino elétrico em carbono e alumínio, ágil e leve. Autonomia curta nas primeiras baterias, suspensão seca e portas traseiras de abertura invertida.'),
    ('BMW', 'i4', 8, 8, 6, 9, 6, 'baixo', 'Berlina elétrica de cinco portas derivada do Série 4 Gran Coupé. Boa de conduzir e eficiente em autoestrada; lugares traseiros baixos e apertados.'),
    ('BMW', 'i5', 9, 7, 4, 10, 7, 'baixo', 'Série 5 elétrico. Muito confortável e silencioso em viagem; grande e pesado, e a autonomia baixa bastante em autoestrada.'),
    ('BMW', 'i7', 10, 6, 3, 10, 8, 'baixo', 'Série 7 elétrico. Extremamente silencioso e confortável, com muito espaço atrás; muito grande, pesado e caro.'),
    ('BMW', 'i8', 6, 8, 4, 7, 1, 'medio', 'Desportivo híbrido plug-in com motor de três cilindros e chassis em carbono. Aspeto de supercarro e consumos baixos; acesso difícil e pouca bagagem.'),
    ('BMW', 'iX', 9, 6, 4, 10, 8, 'baixo', 'SUV elétrico grande, muito silencioso e confortável. Interior espaçoso; pesado e largo para cidade, e o desenho divide opiniões.'),
    ('BMW', 'iX3', 8, 6, 6, 9, 7, 'baixo', 'SUV familiar elétrico. O G08 é um X3 elétrico de tração traseira, eficiente e confortável; o NA5 é um modelo novo, com mais autonomia e carregamento mais rápido.'),
    ('BYD', 'Atto 2', 7, 4, 8, 6, 6, 'baixo', 'SUV compacto vendido como elétrico e, desde o final de 2025, como híbrido plug-in DM-i. Bem equipado e fácil em cidade; a versão elétrica de bateria pequena tem autonomia curta para viagens.'),
    ('BYD', 'Dolphin Surf', 6, 4, 9, 5, 4, 'baixo', 'Citadino elétrico de quatro lugares, bem equipado para o preço. Pensado para cidade: a versão de 30 kWh tem autonomia curta fora dela.'),
    ('BYD', 'Seal 6', 8, 4, 6, 8, 8, 'baixo', 'Familiar híbrido plug-in em berlina ou carrinha Touring. Consumos baixos e grande autonomia total; condução orientada para o conforto.'),
    ('BYD', 'Seal U', 8, 4, 6, 8, 8, 'baixo', 'SUV familiar vendido como elétrico e como híbrido plug-in DM-i. Espaçoso e bem equipado; suspensão mole e direção pouco comunicativa.'),
    ('BYD', 'Sealion 7', 8, 6, 5, 8, 7, 'baixo', 'SUV-coupé elétrico grande e potente, rival do Tesla Model Y. Muito equipamento e acelerações fortes; consumos altos em autoestrada e peso elevado.'),
    ('Citroën', 'C-Elysée', 6, 3, 6, 6, 7, 'medio', 'Berlina de baixo custo com muito espaço atrás e bagageira grande. Materiais simples e equipamento básico; muito usada como táxi e TVDE.'),
    ('Citroën', 'C2', 5, 6, 9, 4, 2, 'medio', 'Citadino de três portas e quatro lugares, curto e ágil. Barato de comprar e manter; pouco espaço atrás e isolamento fraco em estrada.'),
    ('Citroën', 'C3 Picasso', 7, 4, 7, 6, 7, 'medio', 'Pequeno monovolume de formas quadradas, com muito espaço e boa visibilidade. Prático e barato; motores modestos em estrada.'),
    ('Citroën', 'C4 Cactus', 8, 4, 8, 6, 5, 'medio', 'Crossover leve e económico, pensado para o conforto. Suspensão macia e consumos baixos; nos primeiros anos os vidros traseiros só abrem em compasso.'),
    ('Citroën', 'C4 Picasso', 8, 4, 6, 8, 9, 'baixo', 'Monovolume luminoso e confortável, com cinco lugares ou sete na versão Grand. Três bancos traseiros individuais e muita arrumação. Desde 2018 chama-se C4 Spacetourer.'),
    ('Citroën', 'C5', 9, 4, 4, 9, 8, 'baixo', 'Familiar grande centrado no conforto, com suspensão hidropneumática nas versões superiores. Excelente em viagem; a suspensão e a eletrónica podem sair caras com a idade.'),
    ('Citroën', 'C5 X', 9, 4, 5, 9, 7, 'baixo', 'Grande berlina de cinco portas, a meio caminho entre carrinha e SUV. Suspensão muito confortável e habitáculo silencioso. Maioria das unidades em híbrido plug-in.'),
    ('Citroën', 'Saxo', 4, 6, 8, 3, 3, 'alto', 'Citadino leve e simples dos anos 90. Muito barato e fácil de reparar, mas com segurança passiva e isolamento muito abaixo dos padrões atuais.'),
    ('Citroën', 'Spacetourer', 7, 3, 4, 7, 10, 'medio', 'Furgão de passageiros até nove lugares, derivado do Jumpy. Cabe em parques subterrâneos (1,90 m de altura). Desde 2022 vende-se novo sobretudo como elétrico.'),
    ('Cupra', 'Born', 7, 7, 8, 7, 5, 'baixo', 'Compacto elétrico de tração traseira, gémeo do VW ID.3 com afinação mais desportiva. Ágil e bem equipado; comandos táteis pouco práticos.'),
    ('Cupra', 'Tavascan', 7, 7, 6, 8, 6, 'baixo', 'SUV coupé elétrico sobre a plataforma MEB, com tração traseira ou integral. Condução envolvente para um elétrico deste tamanho; visibilidade traseira limitada.'),
    ('Cupra', 'Terramar', 7, 6, 6, 8, 7, 'baixo', 'SUV familiar com a base do VW Tiguan e afinação mais firme. Versões híbridas plug-in com boa autonomia elétrica; preço próximo dos premium.'),
    ('DS', '3', 7, 5, 8, 6, 4, 'baixo', 'SUV urbano de pendor premium, em gasolina, diesel ou elétrico. Interior cuidado e bom conforto; espaço traseiro e visibilidade limitados.'),
    ('DS', '5', 6, 5, 5, 8, 6, 'baixo', 'Cinco portas de desenho original, entre berlina e monovolume. Interior distinto e bom em autoestrada; suspensão firme e visibilidade fraca.'),
    ('Dacia', 'Bigster', 6, 4, 5, 7, 8, 'medio', 'SUV familiar maior do que o Duster, com muito espaço e bagageira grande. Versões híbridas económicas; acabamentos simples face aos rivais.'),
    ('Dacia', 'Lodgy', 5, 3, 5, 6, 9, 'medio', 'Monovolume de sete lugares ao preço de um utilitário. Muito espaço e motores Renault económicos; interior simples e ruído em autoestrada.'),
    ('Dacia', 'Logan MCV', 5, 3, 6, 6, 8, 'medio', 'Carrinha simples com uma das maiores bagageiras do seu preço. Mecânica Renault comprovada e custos baixos; acabamentos básicos e pouca insonorização.'),
    ('Dacia', 'Spring', 4, 3, 9, 3, 3, 'medio', 'Elétrico dos mais baratos do mercado. Pensado para cidade: pequeno, leve e económico; pouca potência, autonomia curta e fraco em autoestrada.'),
    ('Fiat', '124 Spider', 5, 9, 5, 6, 1, 'medio', 'Roadster de dois lugares com base Mazda MX-5 e motor 1.4 turbo. Leve e divertido; mala e habitáculo muito pequenos.'),
    ('Fiat', '500C', 6, 5, 9, 4, 2, 'medio', 'Fiat 500 com teto de lona de enrolar. Mesma facilidade em cidade; mais ruído em estrada e mala ainda mais pequena.'),
    ('Fiat', '500L', 7, 4, 7, 6, 7, 'medio', 'Monovolume compacto alto e luminoso, com muito espaço e bancos versáteis. Condução sem interesse e motores a gasolina fracos.'),
    ('Fiat', '600', 7, 5, 8, 6, 5, 'baixo', 'SUV urbano com estilo do 500, em híbrido ligeiro ou elétrico. Confortável e fácil em cidade; lugares traseiros e mala apenas razoáveis.'),
    ('Fiat', 'Bravo', 6, 5, 6, 7, 5, 'medio', 'Compacto familiar de desenho italiano. Diesel Multijet económicos e mala generosa; visibilidade traseira fraca e revenda baixa.'),
    ('Fiat', 'Doblò', 6, 3, 6, 5, 8, 'alto', 'Furgão de passageiros com portas de correr. Muito espaço e modularidade por pouco dinheiro; condução e insonorização de comercial.'),
    ('Fiat', 'Grande Panda', 7, 5, 8, 6, 5, 'baixo', 'Utilitário de linhas quadradas, em gasolina, híbrido ligeiro ou elétrico. Bom espaço para o tamanho e preço contido; materiais simples.'),
    ('Fiat', 'Punto', 6, 5, 8, 5, 5, 'medio', 'Utilitário italiano simples e barato de manter. Espaçoso para a classe; acabamentos fracos e segurança ultrapassada nas últimas unidades.'),
    ('Ford', 'C-Max', 7, 6, 7, 7, 8, 'baixo', 'Monovolume compacto com base Focus e bom comportamento. Prático no dia a dia; o Grand C-Max acrescenta portas de correr e sete lugares.'),
    ('Ford', 'EcoSport', 5, 5, 7, 5, 5, 'medio', 'SUV pequeno com posição de condução alta e motor 1.0 EcoBoost competente. Mala pequena com porta de abertura lateral e conforto mediano.'),
    ('Ford', 'Explorer', 8, 6, 6, 8, 7, 'baixo', 'SUV familiar elétrico com base Volkswagen MEB. Confortável e bem equipado, com boa autonomia; comandos táteis pouco práticos.'),
    ('Ford', 'Ka', 5, 5, 9, 4, 3, 'medio', 'Citadino de três portas, barato de manter e fácil de estacionar. Pouco espaço e pouco fôlego em estrada.'),
    ('Ford', 'Ka+', 6, 5, 8, 5, 5, 'medio', 'Utilitário de cinco portas simples e espaçoso para o preço. Motor 1.2 atmosférico modesto e equipamento básico.'),
    ('Ford', 'Mondeo', 8, 6, 5, 9, 8, 'baixo', 'Familiar grande, confortável e muito espaçoso, com bom comportamento. Dimensões incómodas em cidade; desvaloriza depressa.'),
    ('Ford', 'Mustang Mach-E', 7, 7, 6, 8, 7, 'baixo', 'SUV elétrico familiar com boa autonomia e comportamento vivo. Suspensão firme e quase tudo comandado pelo ecrã central.'),
    ('Ford', 'Ranger', 6, 4, 3, 7, 6, 'medio', 'Pick-up de cabine dupla com tração integral. Robusta, com boa capacidade de carga e reboque; grande para cidade e consumos altos.'),
    ('Ford', 'Tourneo Courier', 6, 5, 7, 6, 7, 'medio', 'Pequeno monovolume derivado de furgão. Muito espaço em pouco comprimento; acabamentos simples.'),
    ('Hyundai', 'Inster', 6, 4, 9, 5, 4, 'baixo', 'Citadino elétrico alto e estreito, com interior modular. Fácil de estacionar e com autonomia suficiente para o dia a dia; quatro lugares e pouco à vontade em autoestrada.'),
    ('Hyundai', 'Santa Fe', 8, 4, 4, 8, 9, 'baixo', 'SUV grande de sete lugares. Espaçoso, bem equipado e confortável em viagem; grande para a cidade e, nos diesel antigos, com consumos elevados.'),
    ('Jaguar', 'F-Type', 5, 9, 4, 7, 1, 'alto', 'Desportivo de dois lugares, coupé ou descapotável, com motores de quatro, seis e oito cilindros. Som e estilo marcantes; pouca bagageira e custos de manutenção altos.'),
    ('Jaguar', 'I-Pace', 8, 8, 5, 8, 6, 'baixo', 'SUV elétrico de 400 cv com tração integral e condução envolvente. Consumo elevado e carregamento lento para os padrões atuais; forte desvalorização.'),
    ('Jaguar', 'XE', 7, 8, 5, 8, 4, 'baixo', 'Berlina compacta de tração traseira com direção e chassis muito bons. Espaço traseiro e bagageira apertados; fiabilidade dos diesel irregular.'),
    ('Jaguar', 'XF', 8, 7, 4, 9, 6, 'baixo', 'Berlina executiva confortável e agradável de conduzir. Interior menos espaçoso do que os rivais alemães; fiabilidade e custos de manutenção exigem atenção.'),
    ('Jaguar', 'XJ', 9, 7, 3, 10, 6, 'baixo', 'Berlina de luxo em alumínio, mais leve e ágil do que as rivais. Muito confortável em viagem; eletrónica e suspensão pneumática caras de reparar.'),
    ('Jaguar', 'XK', 8, 8, 4, 9, 2, 'medio', 'Grande turismo 2+2 com motor V8, coupé ou descapotável. Confortável e rápido em viagem; lugares traseiros simbólicos e manutenção cara.'),
    ('Jeep', 'Grand Cherokee', 8, 4, 3, 8, 8, 'medio', 'SUV grande americano com verdadeiras capacidades todo-o-terreno. Confortável e bem equipado; consumos altos e acabamentos abaixo dos rivais europeus.'),
    ('Jeep', 'Renegade', 6, 5, 7, 6, 6, 'medio', 'SUV pequeno de linhas quadradas, com versões 4x4 realmente capazes fora de estrada. Boa altura interior, bagageira modesta e ruído de vento em autoestrada.'),
    ('Jeep', 'Wrangler', 4, 6, 4, 4, 5, 'alto', 'Todo-o-terreno puro, com chassis de longarinas, eixos rígidos e tejadilho removível. Imbatível fora de estrada; em asfalto é ruidoso e impreciso. Desvaloriza pouco.'),
    ('Kia', 'Carens', 7, 4, 6, 7, 8, 'medio', 'Monovolume compacto de cinco ou sete lugares. Prático, bem equipado e com garantia longa; condução sem interesse.'),
    ('Kia', 'EV4', 8, 6, 7, 8, 6, 'baixo', 'Compacto elétrico em versão hatchback ou fastback. Boa autonomia e espaço interior; modelo recente, ainda sem historial de fiabilidade.'),
    ('Kia', 'EV9', 9, 5, 3, 9, 10, 'baixo', 'SUV elétrico de seis ou sete lugares. Enorme por dentro e confortável; muito grande e pesado para cidade.'),
    ('Kia', 'Sorento', 8, 5, 4, 9, 9, 'baixo', 'SUV grande de sete lugares, espaçoso e bem equipado. Confortável em viagem; volumoso em cidade e sem grande agilidade.'),
    ('Kia', 'XCeed', 7, 6, 7, 7, 6, 'baixo', 'Ceed com carroçaria elevada e desenho de crossover. Fácil de conduzir e bem equipado, com sete anos de garantia; mala reduzida no plug-in.'),
    ('Kia', 'e-Soul', 7, 5, 8, 6, 6, 'baixo', 'Crossover elétrico de formas quadradas. A geração de 2019 com 64 kWh tem boa autonomia; mala pequena e ruído aerodinâmico em autoestrada.'),
    ('Land Rover', 'Discovery', 8, 4, 3, 8, 10, 'baixo', 'SUV grande de sete lugares verdadeiros, muito capaz fora de estrada. Confortável em viagem; pesado, e com fiabilidade e custos de manutenção que exigem cuidado.'),
    ('Land Rover', 'Range Rover', 10, 5, 3, 10, 8, 'baixo', 'O SUV de luxo de referência, com conforto de limusina e capacidade real fora de estrada. Custos de manutenção e de reparação muito elevados, sobretudo nas gerações mais antigas.'),
    ('Lexus', 'LBX', 7, 5, 8, 6, 4, 'baixo', 'O Lexus mais pequeno, com base de Yaris Cross e interior de nível superior. Híbrido muito económico em cidade; lugares traseiros e bagageira apertados.'),
    ('MG', '3', 6, 6, 8, 6, 5, 'medio', 'Utilitário de preço baixo. O Hybrid+ de 195 cv é rápido e económico para a classe; materiais simples e ajuda à condução por vezes intrusiva.'),
    ('MG', 'Cyberster', 7, 7, 5, 7, 1, 'baixo', 'Roadster elétrico de dois lugares com portas de abertura em tesoura. Muito rápido em linha reta, mas pesado; mais grand tourer do que desportivo puro.'),
    ('MG', 'Marvel R', 8, 5, 6, 8, 7, 'baixo', 'SUV elétrico com interior cuidado e muito equipamento. Autonomia real perto de 350 km e carregamento rápido apenas mediano. Bagageira pequena na versão de tração integral.'),
    ('MG', 'ZS', 6, 4, 7, 6, 6, 'medio', 'SUV compacto de preço baixo e bem equipado. A segunda geração traz o híbrido Hybrid+, mais potente e económico; os motores a gasolina da primeira são modestos.'),
    ('MINI', 'Aceman', 6, 7, 8, 6, 5, 'baixo', 'Crossover elétrico de cinco portas entre o Cooper e o Countryman. Ágil e com interior original; suspensão firme e autonomia real de 300 km ou menos.'),
    ('MINI', 'Cabrio', 6, 8, 8, 6, 2, 'medio', 'Descapotável de quatro lugares com a condução viva do MINI. Bancos traseiros e bagageira muito pequenos; a capota de lona deixa passar mais ruído em autoestrada.'),
    ('Maserati', 'Ghibli', 7, 8, 4, 9, 5, 'medio', 'Berlina desportiva italiana com motores V6 de som marcante. Menos refinada e com interior menos sólido do que as rivais alemãs. Manutenção cara e forte desvalorização.'),
    ('Maserati', 'Levante', 8, 7, 3, 9, 7, 'medio', 'SUV grande de carácter desportivo, com suspensão pneumática de série. Motores V6 com som próprio; consumos, manutenção e desvalorização elevados.'),
    ('Mazda', '6', 7, 7, 5, 8, 7, 'baixo', 'Familiar grande, berlina ou carrinha, com condução acima da média do segmento. Fiável a gasolina; nos diesel antigos convém verificar o filtro de partículas e o nível do óleo.'),
    ('Mazda', '6e', 8, 5, 5, 8, 6, 'baixo', 'Berlina elétrica de cinco portas desenvolvida com a Changan. Espaçosa e bem equipada pelo preço; quase todos os comandos passam pelo ecrã.'),
    ('Mazda', 'CX-60', 7, 7, 4, 8, 7, 'baixo', 'SUV grande de tração traseira, com diesel de seis cilindros ou híbrido plug-in. Interior de qualidade e consumos baixos no diesel; suspensão firme.'),
    ('Mazda', 'MX-30', 7, 6, 8, 5, 4, 'baixo', 'SUV compacto elétrico com portas traseiras de abertura invertida. Agradável de conduzir e bem acabado; autonomia curta e acesso difícil aos lugares de trás.'),
    ('Mercedes-Benz', 'AMG GT', 5, 10, 3, 8, 1, 'alto', 'Desportivo de motor V8 dianteiro e tração traseira (integral na segunda geração). Prestações e som marcantes; pouco prático e com custos de utilização muito altos.'),
    ('Mercedes-Benz', 'AMG GT 4 portas', 8, 9, 3, 9, 5, 'medio', 'Berlina desportiva de cinco portas com base técnica do Classe E. Muito rápida e utilizável no dia a dia; pesada, cara de manter e com consumos elevados.'),
    ('Mercedes-Benz', 'CLK', 7, 5, 5, 8, 3, 'baixo', 'Coupé e cabrio de quatro lugares com mecânica do Classe C. Confortável e discreto; nos mais antigos convém verificar ferrugem e a eletrónica.'),
    ('Mercedes-Benz', 'CLS', 8, 6, 4, 9, 5, 'baixo', 'Berlina de quatro portas com linha de coupé, baseada no Classe E. Confortável e refinada em autoestrada; menos espaço atrás e manutenção cara.'),
    ('Mercedes-Benz', 'Classe G', 7, 6, 3, 7, 6, 'medio', 'Todo-o-terreno de luxo com chassis de longarinas e três bloqueios de diferencial. Capacidade fora de estrada real; consumos e custos de manutenção muito elevados.'),
    ('Mercedes-Benz', 'Classe M', 8, 5, 4, 8, 8, 'medio', 'SUV grande antecessor do GLE. Espaçoso e confortável em viagem; consumos altos e reparações caras na suspensão pneumática e na transmissão.'),
    ('Mercedes-Benz', 'Classe S', 10, 6, 3, 10, 7, 'baixo', 'Berlina de luxo de referência. Conforto, silêncio e tecnologia ao mais alto nível; suspensão pneumática e eletrónica tornam a manutenção muito cara fora da garantia.'),
    ('Mercedes-Benz', 'Classe T', 7, 4, 7, 6, 8, 'medio', 'Monovolume de portas deslizantes derivado da Citan e do Renault Kangoo. Muito espaço e acesso fácil; condução e insonorização de furgão ligeiro.'),
    ('Mercedes-Benz', 'Classe X', 6, 4, 3, 6, 6, 'medio', 'Pick-up de cabine dupla feita sobre a base da Nissan Navara. Interior e conforto acima da média das pick-ups; grande em cidade e carreira comercial curta.'),
    ('Mercedes-Benz', 'EQA', 8, 5, 8, 7, 5, 'baixo', 'SUV compacto elétrico derivado do GLA. Confortável e silencioso, fácil em cidade. Bagageira e autonomia em autoestrada modestas para o preço.'),
    ('Mercedes-Benz', 'EQB', 8, 5, 7, 7, 8, 'baixo', 'SUV elétrico compacto com opção de sete lugares. Espaçoso e confortável; consumo elevado em autoestrada limita a autonomia real.'),
    ('Mercedes-Benz', 'EQC', 9, 6, 5, 8, 6, 'baixo', 'SUV elétrico derivado do GLC, com tração integral e 408 cv. Muito silencioso e confortável; consumo alto e carregamento rápido lento para os padrões atuais.'),
    ('Mercedes-Benz', 'EQE', 9, 6, 5, 9, 6, 'baixo', 'Berlina elétrica grande, muito silenciosa e confortável em autoestrada. Autonomia real elevada; bagageira com abertura pequena e desvalorização acentuada.'),
    ('Mercedes-Benz', 'EQS', 10, 6, 3, 10, 6, 'baixo', 'Topo de gama elétrico da Mercedes. Conforto e silêncio de referência e autonomia real muito elevada; dimensões grandes e forte desvalorização.'),
    ('Mercedes-Benz', 'GLB', 8, 5, 6, 8, 8, 'baixo', 'SUV compacto de formas quadradas, com muito espaço e sete lugares em opção. Confortável em viagem; os motores de entrada são justos com o carro cheio.'),
    ('Mercedes-Benz', 'GLK', 7, 5, 6, 8, 6, 'medio', 'SUV compacto de linhas angulosas, antecessor do GLC. Sólido e confortável em estrada; espaço traseiro e bagageira apenas medianos.'),
    ('Mercedes-Benz', 'SL', 8, 7, 4, 9, 1, 'baixo', 'Roadster de luxo de grande turismo. Confortável e rápido em viagem a dois; sistemas hidráulicos da capota e da suspensão caros de reparar.'),
    ('Mercedes-Benz', 'SLK', 6, 7, 6, 7, 1, 'medio', 'Roadster de dois lugares com capota rígida retrátil. Agradável em passeio e utilizável todo o ano; bagageira reduzida com a capota aberta.'),
    ('Mercedes-Benz', 'Vito Tourer', 6, 3, 3, 7, 9, 'medio', 'Versão de passageiros da Vito, até nove lugares. Muito espaço e motores diesel robustos; acabamentos mais simples e mais ruído do que no Classe V.'),
    ('Mitsubishi', 'ASX', 6, 4, 7, 6, 6, 'medio', 'SUV compacto simples e robusto na primeira geração, com interior datado. Desde 2023 é um Renault Captur com outro emblema, mais moderno e económico.'),
    ('Mitsubishi', 'Colt', 6, 5, 8, 5, 5, 'medio', 'Utilitário prático e alto na geração Z30, com mecânica simples. O Colt de 2023 é um Renault Clio com outro emblema: mais confortável, refinado e com versão híbrida.'),
    ('Mitsubishi', 'Eclipse Cross', 7, 5, 6, 7, 6, 'baixo', 'SUV coupé confortável e bem equipado. O PHEV faz cerca de 45 km em modo elétrico e tem tração integral, mas o depósito e a bagageira são pequenos.'),
    ('Mitsubishi', 'Grandis', 7, 4, 5, 7, 9, 'medio', 'Monovolume de sete lugares com muito espaço e diesel 2.0 de origem Volkswagen. O Grandis de 2025 é outro carro: um SUV compacto de cinco lugares derivado do Renault Symbioz.'),
    ('Mitsubishi', 'L200', 5, 3, 3, 6, 5, 'alto', 'Pick-up de trabalho robusta, com tração integral eficaz fora de estrada. Suspensão traseira dura sem carga, diesel ruidoso e dimensões pouco práticas em cidade.'),
    ('Mitsubishi', 'Outlander', 7, 4, 5, 7, 8, 'baixo', 'SUV familiar espaçoso, com sete lugares nas versões diesel. O PHEV é silencioso e muito económico em percursos curtos com carga diária; em autoestrada com a bateria vazia o consumo sobe bastante.'),
    ('Mitsubishi', 'Pajero', 6, 3, 3, 6, 7, 'alto', 'Todo-o-terreno verdadeiro, com redutoras e grande capacidade fora de estrada. Diesel ruidoso, consumos altos e condução pesada em estrada.'),
    ('Mitsubishi', 'Pajero Sport', 5, 3, 4, 5, 6, 'alto', 'Todo-o-terreno de chassis separado derivado da L200, com redutoras. Simples e resistente; diesel 2.5 lento e ruidoso, conforto de pick-up.'),
    ('Mitsubishi', 'Space Star', 5, 3, 9, 4, 4, 'alto', 'Citadino leve, barato de manter e com consumos muito baixos. Motor de três cilindros ruidoso e pouco à vontade em autoestrada; interior simples.'),
    ('Nissan', 'Almera', 6, 5, 7, 6, 5, 'medio', 'Compacto simples e resistente do início dos anos 2000. Mecânica fiável e barata de manter; segurança e equipamento da época.'),
    ('Nissan', 'Ariya', 8, 5, 6, 8, 7, 'baixo', 'SUV elétrico confortável e silencioso, com interior espaçoso e bem acabado. Autonomia real de 400 km ou mais com a bateria de 87 kWh. Bagageira mediana.'),
    ('Nissan', 'Leaf', 7, 5, 8, 6, 6, 'baixo', 'Compacto elétrico com muitos anos de mercado. Nas duas primeiras gerações a bateria não tem arrefecimento líquido e o carregamento rápido é CHAdeMO, o que pesa em viagens longas.'),
    ('Nissan', 'Navara', 6, 4, 3, 6, 6, 'medio', 'Pick-up de cabine dupla com boa capacidade de carga e de reboque. A geração de 2015 tem suspensão traseira de molas helicoidais, mais confortável do que o habitual na classe.'),
    ('Nissan', 'Note', 6, 4, 8, 5, 6, 'medio', 'Pequeno monovolume com muito espaço interior para o tamanho e banco traseiro deslizante. Prático e económico; pouco entusiasmante de conduzir.'),
    ('Nissan', 'Pulsar', 7, 4, 7, 7, 7, 'baixo', 'Compacto discreto com espaço para pernas atrás acima da média da classe. Condução sem interesse; motores 1.2 DIG-T e 1.5 dCi económicos.'),
    ('Nissan', 'X-Trail', 7, 4, 5, 8, 8, 'medio', 'SUV familiar acima do Qashqai, com sete lugares em opção desde 2014. Espaçoso e confortável em viagem; a geração atual só existe com motorização e-Power ou mild-hybrid.'),
    ('Opel', 'Crossland', 7, 4, 8, 6, 6, 'medio', 'SUV urbano de base PSA, com posição de condução alta e boa bagageira. Fácil de conduzir e económico; condução pouco envolvente.'),
    ('Opel', 'Frontera', 6, 4, 7, 6, 7, 'medio', 'SUV compacto e prático, com versões híbrida ligeira e elétrica. Espaçoso para o preço; acabamentos simples e prestações modestas.'),
    ('Opel', 'Insignia', 8, 5, 5, 9, 7, 'baixo', 'Familiar grande, berlina ou carrinha, confortável e estável em autoestrada. Muito equipamento por pouco dinheiro em usado; grande em cidade.'),
    ('Opel', 'Meriva', 7, 4, 8, 5, 7, 'medio', 'Monovolume compacto com banco traseiro modular; a segunda geração tem portas traseiras de abertura invertida. Prático e fácil em cidade; motores de entrada fracos.'),
    ('Opel', 'Zafira', 7, 4, 5, 7, 9, 'medio', 'Monovolume de sete lugares com bancos rebatíveis no piso. Prático e barato em usado; nos diesel antigos, atenção a injetores, EGR e filtro de partículas.'),
    ('Peugeot', '107', 4, 4, 9, 3, 3, 'alto', 'Citadino simples feito com a Toyota e a Citroën. Motor 1.0 de três cilindros fiável e muito económico; ruidoso e limitado em autoestrada.'),
    ('Peugeot', '206', 5, 5, 8, 4, 4, 'medio', 'Utilitário muito vendido, simples e barato de manter. Carros já antigos: verificar eixo traseiro, eletrónica e corrosão.'),
    ('Peugeot', '207', 6, 5, 8, 5, 4, 'medio', 'Utilitário muito comum em usado. Diesel HDi económicos e peças baratas; os motores a gasolina VTi e THP têm problemas conhecidos de corrente de distribuição.'),
    ('Peugeot', '207 CC', 6, 5, 7, 5, 2, 'medio', 'Descapotável de capota rígida retrátil com base no 207. Agradável em passeio; lugares traseiros simbólicos e mecanismo da capota a verificar.'),
    ('Peugeot', '307', 7, 4, 7, 6, 6, 'medio', 'Compacto espaçoso e confortável, também em carrinha e SW de sete lugares. Diesel HDi duráveis; problemas elétricos frequentes nos primeiros anos.'),
    ('Peugeot', '407', 8, 5, 5, 8, 6, 'baixo', 'Berlina familiar confortável, com boa estabilidade em estrada. Diesel HDi económicos; suspensão dianteira e eletrónica pedem atenção com a idade.'),
    ('Peugeot', '408', 8, 6, 6, 8, 7, 'baixo', 'Fastback elevado derivado do 308, com mais espaço traseiro e bagageira. Confortável e distinto; visibilidade traseira limitada e preço acima do 308.'),
    ('Peugeot', 'RCZ', 6, 8, 6, 7, 2, 'medio', 'Coupé 2+2 com base no 308 e comportamento eficaz. Lugares traseiros simbólicos; nos 1.6 THP, atenção à corrente de distribuição e ao consumo de óleo.'),
    ('Peugeot', 'Traveller', 7, 3, 3, 7, 10, 'medio', 'Versão de passageiros da Expert, até nove lugares. Mais confortável do que um furgão adaptado; dimensões grandes para cidade.'),
    ('Polestar', '2', 7, 7, 7, 8, 5, 'baixo', 'Berlina elétrica de cinco portas com construção sólida e sistema Google integrado. Suspensão firme e lugares traseiros acanhados; tração dianteira até 2023, traseira depois da atualização.'),
    ('Polestar', '3', 9, 7, 4, 9, 7, 'baixo', 'SUV elétrico grande de cinco lugares, com suspensão pneumática e bateria de 111 kWh. Confortável e rápido em estrada; pesado, largo e caro.'),
    ('Polestar', '4', 8, 7, 5, 9, 7, 'baixo', 'SUV coupé elétrico grande, com muito espaço atrás e sem vidro traseiro: a visão para trás faz-se por câmara. Rápido e silencioso; quase tudo se comanda no ecrã central.'),
    ('Porsche', '911', 6, 10, 5, 8, 2, 'medio', 'O desportivo de referência, com motor traseiro e utilização diária possível. Rápido e preciso em qualquer versão; preços e custos de manutenção elevados.'),
    ('Porsche', 'Boxster', 6, 9, 5, 7, 1, 'medio', 'Roadster de motor central, muito equilibrado. Utilizável no dia a dia, com duas malas pequenas; manutenção de Porsche.'),
    ('Porsche', 'Cayman', 6, 10, 5, 7, 1, 'medio', 'Coupé de motor central, preciso e comunicativo. Dois lugares e manutenção cara.'),
    ('Porsche', 'Taycan', 8, 9, 4, 9, 5, 'baixo', 'Berlina elétrica desportiva, com comportamento e travagem de Porsche. Carrega muito depressa; lugares traseiros e mala modestos, forte desvalorização.'),
    ('Renault', '4 E-Tech', 7, 5, 8, 6, 6, 'baixo', 'Crossover elétrico compacto de estilo retro, com a base do Renault 5 E-Tech e mais espaço e bagageira. Autonomia real de cerca de 300 km com a bateria de 52 kWh.'),
    ('Renault', 'Espace', 8, 4, 4, 9, 9, 'baixo', 'Grande familiar de sete lugares, confortável em viagem. A geração de 2015 aproximou-se de um crossover e a de 2023 é um SUV derivado do Austral, só híbrido.'),
    ('Renault', 'Kangoo', 6, 3, 6, 6, 8, 'medio', 'Ludospace prático com portas de correr e muito espaço para carga e família. Origem comercial nota-se nos materiais e no ruído.'),
    ('Renault', 'Laguna', 8, 5, 5, 8, 7, 'baixo', 'Familiar confortável e muito barato em usado. O Laguna II ficou conhecido por avarias elétricas e de turbo; o III é bastante mais fiável.'),
    ('Renault', 'Mégane E-Tech', 7, 6, 8, 7, 5, 'baixo', 'Compacto elétrico em plataforma própria, sem relação técnica com o Mégane a combustão. Ágil e silencioso; espaço atrás e visibilidade traseira limitados.'),
    ('Renault', 'Rafale', 8, 6, 5, 9, 7, 'baixo', 'SUV-coupé de topo da Renault, só híbrido ou híbrido plug-in de 300 cv com tração integral. Espaçoso e bem acabado; eixo traseiro direcional ajuda nas manobras.'),
    ('Renault', 'Symbioz', 7, 5, 7, 7, 7, 'baixo', 'SUV familiar compacto, um Captur alongado com mais bagageira. Híbrido económico; espaço atrás apenas mediano para o comprimento.'),
    ('Renault', 'Talisman', 8, 5, 5, 9, 7, 'baixo', 'Berlina grande e confortável, sucessora do Laguna. Muito espaço e bom equipamento por pouco dinheiro em usado. Existe com quatro rodas direcionais (4Control).'),
    ('Renault', 'Trafic', 6, 3, 3, 7, 9, 'medio', 'Furgão de passageiros de até nove lugares (Passenger, Combi, SpaceClass). Muito espaço e custos razoáveis; condução e acabamentos de comercial.'),
    ('Renault', 'Zoe', 7, 4, 9, 5, 4, 'baixo', 'Citadino elétrico muito comum no mercado de usados. Confirmar sempre se a bateria é própria ou de aluguer. Carregamento rápido DC só em opção e só a partir de 2019.'),
    ('SEAT', 'Altea', 6, 6, 7, 7, 7, 'medio', 'Monovolume compacto com mecânica do grupo Volkswagen e comportamento firme. Prático; suspensão seca e interior de plásticos duros.'),
    ('SEAT', 'Tarraco', 8, 6, 4, 9, 9, 'baixo', 'SUV grande de sete lugares, com a plataforma do Skoda Kodiaq. Espaçoso e estável em autoestrada; terceira fila só para crianças.'),
    ('Skoda', 'Enyaq', 8, 5, 7, 8, 9, 'baixo', 'SUV elétrico familiar sobre a plataforma MEB. Muito espaço, bagageira grande e condução descontraída; carregamento apenas mediano nas primeiras versões.'),
    ('Skoda', 'Rapid', 6, 4, 7, 7, 7, 'medio', 'Compacto simples e espaçoso, entre o Fabia e o Octavia. Mecânica VW conhecida e custos baixos; interior austero e suspensão seca.'),
    ('Smart', 'Forfour', 5, 5, 9, 4, 3, 'medio', 'Citadino de quatro lugares; o W453 tem motor traseiro e base comum ao Renault Twingo. Raio de viragem muito curto; mala pequena e pouco à vontade em autoestrada.'),
    ('Smart', 'Fortwo', 4, 4, 10, 3, 1, 'alto', 'Dois lugares e 2,7 m: estaciona em qualquer lado. Fora da cidade é ruidoso e pouco estável; a caixa automatizada das duas primeiras gerações é lenta.'),
    ('Smart', 'Fortwo Cabrio', 4, 4, 10, 3, 1, 'alto', 'O Fortwo com capota de lona elétrica. Mesma agilidade em cidade e mesmas limitações em estrada, com mais ruído.'),
    ('Suzuki', 'Grand Vitara', 5, 4, 5, 5, 6, 'alto', 'Todo-o-terreno compacto com tração integral e redutoras. Robusto e capaz fora de estrada; ruidoso e gastador em estrada.'),
    ('Tesla', 'Model X', 8, 7, 4, 9, 9, 'baixo', 'SUV elétrico grande com portas traseiras de asa e até sete lugares. Muito rápido e com boa autonomia; qualidade de montagem irregular e reparações caras.'),
    ('Toyota', 'Auris', 7, 4, 7, 7, 6, 'baixo', 'Compacto fiável e discreto, antecessor do Corolla atual. O híbrido é económico em cidade; o 1.4 D-4D é o mais comum em Portugal. Condução sem emoção.'),
    ('Toyota', 'Avensis', 8, 4, 5, 8, 7, 'baixo', 'Familiar grande, fiável e confortável, muito usado como carro de empresa e táxi. Condução neutra e sem emoção. A carrinha é a carroçaria mais procurada.'),
    ('Toyota', 'Aygo', 5, 5, 9, 4, 3, 'alto', 'Citadino simples e barato de manter, gémeo do Citroën C1 e do Peugeot 108. Motor 1.0 de três cilindros económico mas ruidoso; bagageira mínima.'),
    ('Toyota', 'Corolla Cross', 8, 4, 7, 7, 7, 'baixo', 'SUV familiar híbrido entre o C-HR e o RAV4. Económico, espaçoso e fácil de usar; o motor faz-se ouvir em aceleração forte.'),
    ('Toyota', 'Hilux', 5, 3, 3, 6, 6, 'medio', 'Pick-up de trabalho com reputação de indestrutível. Suspensão dura em vazio e direção lenta; mantém muito bem o valor.'),
    ('Toyota', 'Land Cruiser', 7, 3, 3, 7, 8, 'medio', 'Todo-o-terreno de chassis separado, conhecido pela robustez e longevidade. Capaz de tudo fora de estrada; pesado, lento e gastador em asfalto. Mantém muito bem o valor.'),
    ('Toyota', 'Proace Verso', 7, 3, 4, 7, 10, 'medio', 'Furgão de passageiros até nove lugares, gémeo do Citroën Spacetourer e do Peugeot Traveller. Muito espaço e garantia Toyota; condução de comercial.'),
    ('Toyota', 'Verso', 7, 4, 6, 7, 9, 'medio', 'Monovolume compacto com sete lugares em opção e bancos fáceis de rebater. Fiável e prático, sem brilho ao volante.'),
    ('Toyota', 'bZ4X', 8, 5, 6, 7, 7, 'baixo', 'SUV elétrico familiar, confortável e espaçoso atrás. Nos primeiros anos a autonomia em autoestrada e a velocidade de carregamento ficam abaixo dos rivais.'),
    ('Toyota', 'iQ', 5, 5, 10, 4, 1, 'medio', 'Microcarro de menos de três metros com três lugares utilizáveis e um quarto simbólico. Imbatível a estacionar; praticamente sem bagageira.'),
    ('Volkswagen', 'Amarok', 7, 5, 3, 7, 6, 'medio', 'Pick-up de cabine dupla com conforto e interior próximos de um SUV. O V6 TDI é forte e refinado. A segunda geração partilha a base com a Ford Ranger.'),
    ('Volkswagen', 'Arteon', 8, 6, 5, 9, 7, 'baixo', 'Berlina de cinco portas acima do Passat, com muito espaço para pernas atrás e bagageira grande. Excelente em autoestrada; comprido para a cidade.'),
    ('Volkswagen', 'Beetle', 6, 5, 7, 6, 3, 'medio', 'Três portas de estilo retro com mecânica de Golf. Compra-se pela imagem: lugares traseiros e bagageira pequenos. A geração de 2011 conduz-se melhor.'),
    ('Volkswagen', 'Beetle Cabriolet', 6, 5, 7, 5, 3, 'medio', 'Descapotável de quatro lugares e estilo retro, com capota de lona. Agradável para passear; bagageira muito pequena e mais ruído em autoestrada.'),
    ('Volkswagen', 'Caravelle', 7, 4, 3, 7, 10, 'medio', 'Versão de passageiros da Transporter, com oito ou nove lugares. Robusta e muito procurada; interior mais simples do que o da Multivan. A geração de 2025 partilha a base com a Ford Transit Custom.'),
    ('Volkswagen', 'Eos', 7, 6, 6, 7, 3, 'baixo', 'Coupé-cabriolet de quatro lugares com capota rígida retrátil e teto de abrir integrado. Silencioso fechado; o mecanismo e as borrachas da capota exigem manutenção para não haver infiltrações.'),
    ('Volkswagen', 'ID. Buzz', 8, 5, 6, 7, 9, 'baixo', 'Monovolume elétrico de estilo retro, com cinco a sete lugares e muito espaço. Fácil de conduzir para o tamanho; consumo alto em autoestrada limita a autonomia em viagem.'),
    ('Volkswagen', 'ID.4', 8, 5, 7, 8, 8, 'baixo', 'SUV elétrico familiar, espaçoso e confortável. Autonomia real de 350 a 450 km com a bateria de 77 kWh. O sistema de infoentretenimento dos primeiros anos é lento.'),
    ('Volkswagen', 'Jetta', 7, 6, 6, 8, 6, 'baixo', 'Um Golf com mala de três volumes e bagageira grande. Sólido e económico com o 1.9 e o 2.0 TDI; menos procurado em Portugal do que o Golf.'),
    ('Volkswagen', 'Multivan', 8, 4, 4, 8, 10, 'baixo', 'Monovolume grande de sete lugares com interior modular. A geração T7 usa plataforma de automóvel (MQB) e conduz-se como tal; existe em híbrido plug-in. Preços altos em usado.'),
    ('Volkswagen', 'Scirocco', 6, 8, 6, 7, 3, 'medio', 'Coupé de três portas com base de Golf, mais baixo e mais largo. Condução precisa e motores conhecidos; lugares traseiros apertados e má visibilidade para trás.'),
    ('Volkswagen', 'Taigo', 7, 5, 8, 7, 6, 'baixo', 'SUV-coupé derivado do Polo e do T-Cross. Fácil de conduzir e com boa bagageira, mas menos altura atrás do que no T-Cross. Só existe a gasolina.'),
    ('Volkswagen', 'Touareg', 9, 6, 4, 10, 8, 'baixo', 'SUV grande com base partilhada com o Porsche Cayenne e o Audi Q7. Muito confortável e sólido em viagem. Motores grandes, impostos e manutenção caros.'),
    ('Volvo', 'C30', 7, 6, 7, 7, 3, 'baixo', 'Compacto de três portas e quatro lugares. Bem construído e confortável; mala pequena e acesso difícil aos lugares de trás.'),
    ('Volvo', 'C40', 8, 6, 6, 8, 5, 'baixo', 'XC40 elétrico com tejadilho de coupé. Rápido e confortável; menos altura atrás e pior visibilidade traseira do que o XC40.'),
    ('Volvo', 'EX90', 9, 5, 3, 10, 10, 'baixo', 'SUV elétrico de sete lugares. Muito silencioso e espaçoso; pesado e caro.'),
    ('Volvo', 'V50', 7, 5, 6, 8, 6, 'baixo', 'Carrinha compacta com bancos excelentes e construção sólida. Mala pequena para carrinha.')
) AS v(brand, model, comfort, fun, city, highway, family, noise, description)
JOIN brands b ON b.name = v.brand
JOIN vehicle_models vm ON vm.brand_id = b.id AND vm.name = v.model
WHERE NOT EXISTS (SELECT 1 FROM driving_character dc WHERE dc.model_id = vm.id);

-- A single year between two generations (the M2 of 2022, the Amarok of 2021):
-- the cars registered in it are the last of the old one, which now covers it.
-- A longer gap is a model that was off the market and stays a gap.
UPDATE generations g
SET year_end = g.year_end + 1
WHERE g.fuel_type IS NULL AND g.year_end IS NOT NULL
  AND (SELECT MIN(n.year_start) FROM generations n
       WHERE n.model_id = g.model_id AND n.fuel_type IS NULL AND n.year_start > g.year_start) = g.year_end + 2;

COMMIT;
